-- Migration: backfill `BIGINT GENERATED BY DEFAULT AS IDENTITY` on every
-- bigint primary key. Without this, every INSERT into these tables fails
-- with "null value in column 'id' of relation '<table>' violates
-- not-null constraint" because the Drizzle schema declared the columns
-- as plain `bigint primary key` (no default, no sequence, no identity).
--
-- Impact before this migration: NO row was ever successfully inserted
-- into any of the listed tables in any production environment. Every
-- empty state in the app — Call Logs, Audit Log, Knowledge, Lessons,
-- Outbound Leads, Email Messages, Phone Numbers, Spend Alerts, Consent
-- Log, Webhook Deliveries — was empty because the writes were silently
-- failing.
--
-- `ADD GENERATED BY DEFAULT AS IDENTITY` is idempotent-safe via the
-- `IF NOT EXISTS`-style DO blocks. Existing rows (none expected on any
-- current tenant — see scripts that confirmed 0 rows) are preserved.

DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'wireline_audit_log',
    'wireline_call_logs',
    'wireline_agent_lessons',
    'wireline_directives',
    'wireline_knowledge',
    'wireline_spend_alerts',
    'wireline_email_messages',
    'wireline_phone_numbers',
    'wireline_outbound_leads',
    'wireline_consent_log',
    'wireline_webhook_deliveries'
  ]
  LOOP
    -- Only add IDENTITY if the column isn't already an identity column.
    IF NOT EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_name = t
        AND column_name = 'id'
        AND is_identity = 'YES'
    ) THEN
      -- If a default was previously set (legacy bigserial path), drop it
      -- before adding the identity definition; ALTER … ADD GENERATED
      -- requires the column to have no existing default.
      EXECUTE format('ALTER TABLE %I ALTER COLUMN id DROP DEFAULT', t);
      EXECUTE format(
        'ALTER TABLE %I ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY',
        t
      );

      -- Sync the identity counter past any rows that may already exist
      -- (defensive — tenants in this environment have zero rows, but
      -- restored snapshots or imports could have non-zero data).
      EXECUTE format(
        'SELECT setval(pg_get_serial_sequence(''%I'', ''id''),
                       COALESCE((SELECT MAX(id) FROM %I), 0) + 1, false)',
        t, t
      );
    END IF;
  END LOOP;
END $$;
